        const rows = findCollection_(res.json, ['roles', 'data', 'records']) || [];
        rows.forEach((r) => out.push({ id: pick_(r, ['id', 'role_id']), name: findRoleName_(r), isDefault: !!r.is_default,
          categoryId: pick_(r, ['category_id', 'role_category_id']), employeeIds: numericList_(r.employee_ids),
          excludedEmployeeIds: numericList_(r.excluded_employee_ids), groupIds: numericList_(r.group_ids),
          assignedCount: (typeof r.assigned_employees_count === 'number') ? r.assigned_employees_count : null, raw: r }));
        if (rows.length < 50) break;
