    let deleteRows = [];
    const deleteTableWrap = el('div', { style: { maxHeight: '42vh', overflow: 'auto', border: '1px solid #e8eaed', borderRadius: '8px' } });
    const deleteTable = el('table', { class: 'jbo-table' });
