    const out = [];
    const re = /(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(a\.?\s?m\.?|p\.?\s?m\.?|ص|م)?(?![\d:])/gi;
    let m;
    while ((m = re.exec(s))) {
      let H = +m[1];
      const M = +m[2];
      const ap = (m[4] || '').toLowerCase().replace(/[.\s]/g, '');
      if (ap === 'pm' || ap === 'م') { if (H < 12) H += 12; } else if ((ap === 'am' || ap === 'ص') && H === 12) H = 0;
      if (H > 23 || M > 59) continue;
      out.push({ H, M });
    }
    if (!out.length) {
      const d = s.trim().match(/^(\d{1,2})\.(\d{2})$/);
      if (d && +d[1] <= 23 && +d[2] <= 59) out.push({ H: +d[1], M: +d[2] });
    }
