      const search = el('input', { class: 'jbo-input', value: S.search, placeholder: T('Search name, code or ID…', 'ابحث بالاسم أو الرقم الوظيفي أو الهوية…'), style: { maxWidth: '280px', margin: '8px 0' } });
      search.addEventListener('input', () => { S.search = search.value; renderTable_(); });
