      body.appendChild(el('div', { class: 'jgc-legend' }, [el('span', {}, [el('i', { style: { background: '#1a73e8' } }), T('GOSI wage', 'أجر التأمينات')]), el('span', {}, [el('i', { style: { background: '#202124' } }), T('Jisr basic + housing', 'الأساسي + السكن في جسر')])]));
