      if (!e) { p.skip = true; p.warnings = ['Could not read this employee\'s current salary and allowances - NOT sent (sending none would wipe them).']; return; }
      const types = await earningTypes_().catch(() => []);
      const a = applyAllowances_(e.benefits, p.body.allowances, types, this.seenTypeIds);
      if (a.errors.length) { p.skip = true; p.warnings = a.errors; return; }
