      const kept = a.benefits.filter((b) => !Object.keys(p.body.allowances).some((n) => normA_(n) === normA_(b.name)));
      p.warnings.push('Other allowances kept as they are: ' + (kept.length ? kept.map((b) => (b.name || 'allowance') + ' ' + b.company_contribution).join(', ') : 'none') + '.');
