  let jobTitles_ = null;
  async function jobTitlesList_() {
    if (jobTitles_) return jobTitles_;
    const arr = await JobTitlesModule.fetchAll();
    jobTitles_ = arr.filter((t) => t && t.id != null).map((t) => ({ id: t.id, name: String(t.name || '').trim(), name_ar: String(t.name_ar || '').trim() }));
    return jobTitles_;
  }
  const jtLabel_ = (t) => (t.name || t.name_ar) + (t.name && t.name_ar && t.name_ar !== t.name ? ' / ' + t.name_ar : '') + ' · #' + t.id;
  /** "Accountant", "محاسب", "Accountant / محاسب · #573327", "573327" -> job title, or null */
  function findJobTitle_(list, txt) {
    const v = String(txt == null ? '' : txt).trim(); if (!v) return null;
    const hash = (v.match(/#(\d+)\s*$/) || [])[1];
    if (hash) return list.find((t) => String(t.id) === hash) || null;
    const k = v.toLowerCase();
    const hits = list.filter((t) => t.name.toLowerCase() === k || t.name_ar.toLowerCase() === k || String(t.id) === v);
    return hits.length === 1 ? hits[0] : null;
  }
  /** The employee's current job title from the profile (read leniently: the field name is not captured). */
  async function currentJobTitle_(empId) {
    const res = await apiGet_(`/v2/employees/${empId}`);
    const e = res.ok && res.data && res.data.data && (res.data.data.employee || res.data.data);
    if (!e) return null;
    let hit = null;
    (function walk(v, d) {
      if (hit || !v || typeof v !== 'object' || d > 4) return;
      for (const k of Object.keys(v)) {
        const x = v[k];
        if (/^job_title$/i.test(k) && x && typeof x === 'object' && x.id != null) { hit = { id: x.id, name: x.name || x.name_i18n || x.name_ar || '' }; return; }
        if (/^job_title_id$/i.test(k) && x != null && typeof x !== 'object') { hit = { id: x, name: v.job_title_name || v.job_title_i18n || (typeof v.job_title === 'string' ? v.job_title : '') }; return; }
      }
      Object.keys(v).forEach((k) => { if (!/^(line_manager|manager|parent|roles?)$/i.test(k)) walk(v[k], d + 1); });
    })(e, 0);
    return hit;
  }
