    if (!r.ok) throw new Error(T('Could not read offboarding reasons (HTTP ', 'تعذّرت قراءة أسباب إنهاء الخدمة (HTTP ') + r.status + ')' + (jisrMsg_(r.json) ? ': ' + jisrMsg_(r.json) : ''));
