    const list = ((j.data && j.data.payroll_transaction_types) || []).map((t) => ({ id: t.id, name: String(t.name_i18n || t.name || '').trim(), nameAr: String(t.name_ar || '').trim(), nameEn: String(t.name || '').trim() }));
