      if (!confirm(T('Apply changes to ', 'تطبيق التغييرات على ') + todo.length + T(' final settlement(s) in ', ' تسوية نهائية في ') + slug_() + (nApprove ? T(' and approve ', ' واعتماد ') + nApprove : '') + '?')) return;
