          const nw = r.action === 'delete' ? T('deleted', 'حذف') : r.ch ? [r.ch.amount != null ? fmt_(r.ch.amount) : null, r.ch.effective, r.ch.paid ? T('paid ', 'دفع ') + r.ch.paid : null, r.ch.note != null ? '“' + r.ch.note + '”' : null].filter(Boolean).join(' · ') : '—';
