      const help = XLSX.utils.aoa_to_sheet([['How to edit'], ['Change the Step columns only. Pick the approver from the dropdown (every employee, "code · name"), or type the employee code (e.g. 1001) or the exact full name.'], ['Steps are saved in order from Step 1; leave the rest blank. A row whose steps did not change is skipped.'], ['Approvers that are not employees (shown as Jisr returned them) can be kept as they are.'], ['Do not change the ID columns.']]);
      help['!cols'] = [{ wch: 110 }];
