      try { await W.__jisrBulkOpsXlsx.saveWithDropdowns(wb, 'jisr-approval-cycles-' + slug_() + '.xlsx', picks); }
      catch (e) { XLSX.writeFile(wb, 'jisr-approval-cycles-' + slug_() + '.xlsx'); }
