        const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false });
        const h = (aoa[0] || []).map((x) => clean_(x).toLowerCase());
        const ci = h.findIndex((x) => x === 'cycle id'), ti = h.findIndex((x) => x === 'request type id');
        const sc = h.map((x, i) => (/^step \d+/.test(x) ? i : -1)).filter((i) => i >= 0);
        if (ci < 0 || ti < 0 || !sc.length) throw new Error(T('Use the Excel from this tool (Request type ID, Cycle ID and Step columns).', 'استخدم ملف Excel من هذه الأداة (أعمدة Request type ID و Cycle ID و Step).'));
