        const r = await request_('GET', '/v2/form_templates', { page, per_page: 50, 'sort_by[created_at]': 'DESC', 'filter[is_available_to_admins]': adm });
        if (!r.ok) { if (page === 1 && adm === 'true') throw new Error(T('Could not read the performance templates (HTTP ', 'تعذّرت قراءة نماذج الأداء (HTTP ') + r.status + ')'); break; }
