        const emps = await W.__jisrBulkOpsEmployees.get(false, (n) => { statusEl.textContent = T('Loading employees… ', 'جارٍ تحميل الموظفين… ') + n; });
        const m = new Map(); emps.forEach((e) => { const k = digits_(e.code); if (k && !m.has(k)) m.set(k, { name: e.name || '', nameAr: e.nameAr || '' }); }); S.jisr = m;
        const want = new Set(clean_(S.only).split(/[\s,;،]+/).filter(Boolean).map(digits_));
        const list = emps.filter((e) => clean_(e.code) && (!want.size || want.has(digits_(e.code)))).sort((a, b) => String(a.code).localeCompare(String(b.code), undefined, { numeric: true }));
