        const en = el('input', { type: 'text', class: 'jpt-en', value: sh.en, placeholder: T('Template name (EN)', 'اسم النموذج (EN)') }); en.addEventListener('change', () => { sh.en = en.value; sh.nameEdited = true; invalidate_(); });
        const ar = el('input', { type: 'text', class: 'jpt-ar', value: sh.ar, placeholder: T('Template name (AR)', 'اسم النموذج (AR)'), dir: 'rtl' }); ar.addEventListener('change', () => { sh.ar = ar.value; sh.nameEdited = true; invalidate_(); });
        const p = sh.parsed;
