  const ALL_ITEMS = []; SECTIONS.forEach((s) => s.groups.forEach((g) => g.items.forEach((it) => ALL_ITEMS.push({ sec: s, id: it[0], en: it[1], ar: it[2], hen: it[3], har: it[4], opt: it[5] || {} }))));
